def find_multiple():
    # Find the Least Common Multiple (LCM) of 9 and 12
    def lcm(a, b):
        def gcd(a, b):
            while b:
                a, b = b, a % b
            return a
        return a * b // gcd(a, b)

    lcm_value = lcm(9, 12)

    # Check which of the given choices is a multiple of the LCM
    choices = [36, 15, 17, 5, 7]
    for choice in choices:
        if choice % lcm_value == 0:
            return choice

answer = find_multiple()
